<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require __DIR__.'/../includes/bootstrap.php';
set_exception_handler(function(Throwable $e):void{fwrite(STDERR,$e->getMessage()."\n".$e->getTraceAsString()."\n");exit(1);});
function check(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
function denied(callable $call,string $message):void{try{$call();}catch(RuntimeException|InvalidArgumentException $e){return;}throw new RuntimeException($message);}
check(function_exists('club_calendar_occurrences'),'Community calendar must exist');
$base=['id'=>1,'title'=>'Sunday club','slug'=>'fixture','event_date'=>'2026-03-22','end_date'=>null,'start_time'=>'19:00:00','end_time'=>'21:00:00','recurrence'=>'weekly','recurrence_end_date'=>'2026-04-12','visibility'=>'public'];
$items=club_expand_event($base,'2026-03-20','2026-04-12');check(count($items)===4,'Weekly recurrence creates actual dates');check($items[0]['start_at']->format('P')==='+00:00'&&$items[1]['start_at']->format('P')==='+01:00','DST transition changes UTC offset');check($items[1]['start_at']->format('H:i')==='19:00','DST preserves club local start time');
check(count(club_expand_event($base,'2026-03-20','2026-04-12',['2026-03-29']))===3,'Cancellation removes only one occurrence');
$monthly=array_merge($base,['event_date'=>'2026-01-31','recurrence'=>'monthly','recurrence_end_date'=>'2026-04-30']);$items=club_expand_event($monthly,'2026-01-01','2026-04-30');check(array_column($items,'occurrence_date')===['2026-01-31','2026-03-31'],'Monthly day 31 skips short months without drift');
$overnight=array_merge($base,['event_date'=>'2026-10-24','start_time'=>'23:30:00','end_time'=>'02:30:00','recurrence'=>'none']);$items=club_expand_event($overnight,'2026-10-25','2026-10-25');check(count($items)===1&&$items[0]['end_at']->format('Y-m-d')==='2026-10-25','Overnight events overlap next-day list');
$midnight=array_merge($base,['start_time'=>'23:00:00','end_time'=>'00:00:00','recurrence'=>'none']);$times=club_event_times($midnight,'2026-03-22');check($times['end_at']->format('Y-m-d H:i')==='2026-03-23 00:00','Midnight is a valid overnight end');
$allDay=array_merge($base,['start_time'=>null,'end_time'=>null,'event_date'=>'2026-10-24','end_date'=>'2026-10-25','recurrence'=>'none']);$items=club_expand_event($allDay,'2026-10-01','2026-10-31');$ics=club_calendar_ics($items);check(str_contains($ics,'DTSTART;VALUE=DATE:20261024')&&str_contains($ics,'DTEND;VALUE=DATE:20261026'),'All-day date semantics use exclusive ICS end');
denied(fn()=>club_content_payload('event',['title'=>'Invalid','description'=>'Details','event_date'=>'2026-02-30']),'Invalid date accepted');
denied(fn()=>club_content_payload('event',['title'=>'Invalid','description'=>'Details','event_date'=>'2026-01-01','start_time'=>'20:00','end_time'=>'20:00']),'Zero-duration event accepted');
denied(fn()=>club_event_wall_time('2026-03-29','01:30'),'Spring missing hour accepted');
denied(fn()=>club_event_wall_time('2026-10-25','01:30'),'Autumn repeated hour accepted');
denied(fn()=>club_content_payload('event',['title'=>'Invalid repeat','description'=>'Details','event_date'=>'2026-03-22','start_time'=>'01:30','end_time'=>'03:00','recurrence'=>'weekly','recurrence_end_date'=>'2026-04-05']),'Future recurring missing hour accepted');
$pdo=db();$pdo->beginTransaction();
try{
    $tag='community-test-'.bin2hex(random_bytes(5));$users=[];
    foreach(['author','other','publisher','treasurer'] as $name){$pdo->prepare("INSERT INTO club_users(full_name,email,password_hash,email_verified_at,status) VALUES(?,?,?,NOW(),'active')")->execute([$name,$tag.'-'.$name.'@example.invalid','unused']);$users[$name]=(int)$pdo->lastInsertId();$role=in_array($name,['publisher','treasurer'],true)?$name:'member';$pdo->prepare('INSERT INTO club_user_roles(user_id,role) VALUES(?,?)')->execute([$users[$name],$role]);if($role==='member')$pdo->prepare("INSERT INTO club_memberships(user_id,status,starts_on,expires_on,external_ref) VALUES(?,'active','2020-01-01','2099-01-01',?)")->execute([$users[$name],$tag.$name]);}
    $_SESSION['club_user_id']=$users['author'];unset($_SESSION['club_auth_sig'],$_SESSION['admin_id']);
    $count=(int)$pdo->query('SELECT COUNT(*) FROM club_posts')->fetchColumn();
    denied(fn()=>club_content_save('post',null,['title'=>$tag.' bad upload','content'=>'Text'],true,['name'=>['bad.exe'],'type'=>['application/octet-stream'],'tmp_name'=>['missing'],'error'=>[UPLOAD_ERR_PARTIAL],'size'=>[1]]),'Invalid upload accepted');
    check((int)$pdo->query('SELECT COUNT(*) FROM club_posts')->fetchColumn()===$count,'Upload failure did not roll back submitted text');
    $input=['title'=>$tag,'description'=>'Original details','event_date'=>'2026-10-20','start_time'=>'19:00','end_time'=>'21:00','visibility'=>'members','recurrence'=>'weekly','recurrence_end_date'=>'2026-11-10'];
    $saved=club_content_save('event',null,$input,true);$eventId=$saved['id'];
    $pdo->prepare('UPDATE events SET featured_image=? WHERE id=?')->execute(['legacy-public-photo.jpg',$eventId]);denied(fn()=>club_content_save('event',$eventId,$input,true),'Legacy public image allowed in members-only event');$pdo->prepare('UPDATE events SET featured_image=NULL WHERE id=?')->execute([$eventId]);
    $_SESSION['club_user_id']=$users['other'];denied(fn()=>club_content_save('event',$eventId,array_merge($input,['title'=>'Stolen']),true),'Member edited another member event');
    $_SESSION['club_user_id']=$users['treasurer'];denied(fn()=>club_content_moderate('event',$eventId,'approve'),'Treasurer can publish');
        $_SESSION['club_user_id']=$users['publisher'];$reviewHash=club_content_review_hash('event',$eventId);$_SESSION['club_user_id']=$users['author'];club_content_save('event',$eventId,array_merge($input,['description'=>'Updated before approval']),true);$_SESSION['club_user_id']=$users['publisher'];denied(fn()=>club_content_moderate('event',$eventId,'approve','',null,$reviewHash),'Stale review approved changed content');club_content_moderate('event',$eventId,'approve');
    unset($_SESSION['club_user_id']);$public=club_calendar_occurrences('2026-10-01','2026-11-30',true);check(!in_array($eventId,array_column($public,'id')),'Public opt-in leaks member events');check(!str_contains(club_calendar_ics($public),$tag),'Private event leaked into public ICS');
    $_SESSION['club_user_id']=$users['author'];$private=club_calendar_occurrences('2026-10-01','2026-11-30',true);check(count(array_filter($private,fn($r)=>(int)$r['id']===$eventId))===4,'Active member sees private recurrence');
    $oldRevision=club_content_save('event',$eventId,array_merge($input,['title'=>$tag.' earlier revision']),true);$revision=club_content_save('event',$eventId,array_merge($input,['title'=>$tag.' revised']),true);check($oldRevision['owner_id']!==$revision['owner_id'],'Pending revisions mutated in place');check($revision['owner_type']==='revision','Published edit bypasses revision');check(club_community_record('event',$eventId)['title']===$tag,'Published content replaced before approval');
    $_SESSION['club_user_id']=$users['publisher'];denied(fn()=>club_content_moderate('event',$eventId,'approve','',$oldRevision['owner_id']),'Superseded revision approved');club_content_moderate('event',$eventId,'approve','Looks good',$revision['owner_id']);check(club_community_record('event',$eventId)['title']===$tag.' revised','Approved revision not applied');
    club_cancel_event($eventId,'occurrence','2026-10-27','Fixture cancellation');$items=club_calendar_occurrences('2026-10-01','2026-11-30',true);check(count(array_filter($items,fn($r)=>(int)$r['id']===$eventId))===3,'Published cancellation did not remove occurrence');
    club_cancel_event($eventId,'series',null,'Fixture series cancellation');$items=club_calendar_occurrences('2026-10-01','2026-11-30',true);check(!in_array($eventId,array_column($items,'id')),'Cancelled series remains visible');
    $_SESSION['club_user_id']=$users['author'];$post=club_content_save('post',null,['title'=>$tag.' post','content'=>'<script>malicious()</script>'],true);check(!str_contains(club_community_record('post',$post['id'])['content'],'<script>'),'Member content allows HTML injection');
    $_SESSION['club_user_id']=$users['publisher'];club_content_moderate('post',$post['id'],'approve');$_SESSION['club_user_id']=$users['author'];$postRevision=club_content_save('post',$post['id'],['title'=>$tag.' post changed','content'=>'New text'],true);$_SESSION['club_user_id']=$users['publisher'];club_content_moderate('post',$post['id'],'reject','Please clarify',$postRevision['owner_id']);check(club_community_record('post',$post['id'])['title']===$tag.' post','Rejected revision changed public post');
    denied(fn()=>club_cancel_event($eventId,'occurrence','2026-10-26','Test'),'Invalid occurrence accepted');
    echo "Community tests passed: ownership, moderation, revisions, visibility, DST, recurrence, cancellation and ICS.\n";
}finally{if($pdo->inTransaction())$pdo->rollBack();unset($_SESSION['club_user_id'],$_SESSION['club_auth_sig']);}
